import { ServerClient } from "postmark";

let client: ServerClient | undefined;

export function getPostmark(): ServerClient {
  const token = process.env.POSTMARK_SERVER_TOKEN;
  if (!token) throw new Error("POSTMARK_SERVER_TOKEN is not set");
  client ??= new ServerClient(token);
  return client;
}
EOF
cat > src/lib/email.ts <<'EOF'
import { getPostmark } from "@/lib/postmark";
import type { User } from "@/lib/users";

function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
}

async function send(to: string, subject: string, html: string, text: string) {
  const from = process.env.POSTMARK_FROM_EMAIL;
  if (!from) throw new Error("POSTMARK_FROM_EMAIL is not set");
  await getPostmark().sendEmail({
    From: from,
    To: to,
    Subject: subject,
    HtmlBody: html,
    TextBody: text,
    MessageStream: process.env.POSTMARK_MESSAGE_STREAM || "outbound",
  });
}

export async function sendWelcomeEmail(user: User) {
  const url = process.env.APP_URL ?? "http://localhost:3000";
  await send(
    user.email,
    "Welcome to Notely",
    `<p>Hi ${escapeHtml(user.name)},</p><p>Welcome to Notely! <a href="${url}/dashboard">Open your dashboard</a>.</p>`,
    `Hi ${user.name},\n\nWelcome to Notely! Open your dashboard: ${url}/dashboard`,
  );
}

export async function sendPasswordResetEmail(user: User, token: string) {
  const url = process.env.APP_URL ?? "http://localhost:3000";
  const link = `${url}/reset-password?token=${encodeURIComponent(token)}`;
  await send(
    user.email,
    "Reset your Notely password",
    `<p>Hi ${escapeHtml(user.name)},</p><p><a href="${link}">Reset your password</a>. This link expires in 1 hour. If you didn't ask for this, ignore this email.</p>`,
    `Hi ${user.name},\n\nReset your password: ${link}\nThis link expires in 1 hour. If you didn't ask for this, ignore this email.`,
  );
}
EOF
